package com.ping.interest;
import java.util.*;import jakarta.validation.Valid;
import com.ping.auth.*;import com.ping.web.*;
import org.springframework.stereotype.Service;import org.springframework.context.annotation.Profile;import org.springframework.transaction.annotation.*;import org.springframework.validation.annotation.Validated;import org.springframework.jdbc.core.JdbcTemplate;
@Service @Profile("!bootstrap") @Validated @Transactional(readOnly=true)
public class TaxonomyAdminService {
 private final JdbcTemplate jdbc;private final InterestCatalogService catalog;private final InterestRepository interests;private final AuthSupport auth;private final AccountService accounts;
 public TaxonomyAdminService(JdbcTemplate j,InterestCatalogService c,InterestRepository i,AuthSupport a,AccountService s){jdbc=j;catalog=c;interests=i;auth=a;accounts=s;}
 private void general(){if(!auth.require().general())throw new org.springframework.security.access.AccessDeniedException("Solo administración general puede mantener la taxonomía.");}
 public record Node(String key,String label,String parent,boolean active,long revision){}
 public List<Node> list(){general();return jdbc.query("select node_key,label,parent_key,active,revision from interest_nodes order by label,node_key",(r,n)->new Node(r.getString(1),r.getString(2),r.getString(3),r.getBoolean(4),r.getLong(5)));}
 public TaxonomyForm form(String key){var n=list().stream().filter(x->x.key().equals(key)).findFirst().orElseThrow(()->new NotFoundException("No encontramos ese grupo."));var f=new TaxonomyForm();f.setNodeKey(n.key());f.setLabel(n.label());f.setParent(Objects.toString(n.parent(),""));f.setActive(n.active());f.setRevision(n.revision());f.setInterestIds(jdbc.query("select interest_id from interest_node_members where node_key=? order by interest_id",(r,i)->r.getLong(1),key));return f;}
 @Transactional(isolation=Isolation.READ_COMMITTED)
 public String save(String key,@Valid TaxonomyForm f){general();catalog.lock();var nodes=list();var byKey=new HashMap<String,Node>();nodes.forEach(n->byKey.put(n.key(),n));String id=key==null?f.getNodeKey():key;if(key!=null&&!key.equals(f.getNodeKey()))throw new BusinessRuleException("La clave estable no se puede cambiar.");if(key==null&&byKey.containsKey(id))throw new BusinessRuleException("Ya existe esa clave de grupo.");if(key!=null&&(!byKey.containsKey(id)||byKey.get(id).revision()!=f.getRevision()))throw new BusinessRuleException("El grupo cambió. Revisa la versión guardada antes de repetir.");String parent=f.getParent().strip();if(!parent.isEmpty()&&!byKey.containsKey(parent))throw new BusinessRuleException("Elige un grupo padre existente.");var seen=new HashSet<String>();String cursor=parent;while(cursor!=null&&!cursor.isEmpty()){if(cursor.equals(id)||!seen.add(cursor))throw new BusinessRuleException("La jerarquía no puede contener ciclos.");cursor=byKey.get(cursor).parent();}
 var selected=new LinkedHashSet<>(f.getInterestIds());if(interests.findAllById(selected).size()!=selected.size())throw new BusinessRuleException("Elige intereses existentes. No se crean por nombre.");if(key==null)jdbc.update("insert into interest_nodes(node_key,label,parent_key,active,revision) values(?,?,?,?,0)",id,f.getLabel().strip(),parent.isBlank()?null:parent,f.isActive());else jdbc.update("update interest_nodes set label=?,parent_key=?,active=?,revision=revision+1 where node_key=?",f.getLabel().strip(),parent.isBlank()?null:parent,f.isActive(),id);jdbc.update("delete from interest_node_members where node_key=?",id);for(long interest:selected)jdbc.update("insert into interest_node_members(node_key,interest_id) values(?,?)",id,interest);accounts.audit(auth.require().id(),"UPDATE_TAXONOMY",null,null);return id;}
}
